// Minimal re-implementation of the subset of Python's argparse used by
// the original script: required string options, -h/--help, usage and
// error formatting, exit codes (0 for help, 2 for argument errors).
import path from 'node:path';

export class ArgumentParser {
  constructor() {
    // -h/--help is added automatically, like argparse does.
    this._options = [
      { names: ['-h', '--help'], dest: 'help', help: 'show this help message and exit', isHelp: true },
    ];
  }

  add_argument(name, { type = 'str', required = false, help = '' } = {}) {
    if (type !== 'str') {
      throw new Error(`unsupported argument type: ${type}`);
    }
    const dest = name.replace(/^--?/, '');
    this._options.push({ names: [name], dest, metavar: dest.toUpperCase(), required, help });
  }

  _prog() {
    return path.basename(process.argv[1] || 'test8.mjs');
  }

  _usageLine() {
    const parts = this._options.map((opt) => {
      if (opt.isHelp) return '[-h]';
      return `${opt.names[0]} ${opt.metavar}`;
    });
    return `usage: ${this._prog()} ${parts.join(' ')}`;
  }

  _helpText() {
    const invocations = this._options.map((opt) =>
      opt.isHelp ? '-h, --help' : `${opt.names[0]} ${opt.metavar}`,
    );
    const maxLen = Math.max(...invocations.map((s) => s.length));
    const helpCol = 2 + maxLen + 2;
    const lines = [this._usageLine(), '', 'options:'];
    for (let i = 0; i < this._options.length; i++) {
      const inv = '  ' + invocations[i];
      lines.push(inv.padEnd(helpCol) + this._options[i].help);
    }
    return lines.join('\n');
  }

  _error(message) {
    process.stderr.write(this._usageLine() + '\n');
    process.stderr.write(`${this._prog()}: error: ${message}\n`);
    process.exit(2);
  }

  parse_args(argv = process.argv.slice(2)) {
    const result = {};
    const extras = [];
    const seen = new Set();
    const valueOpts = this._options.filter((o) => !o.isHelp);

    const findOption = (name) => {
      const exact = this._options.find((o) => o.names.includes(name));
      if (exact) return exact;
      // argparse allows unambiguous abbreviations of long options.
      if (name.startsWith('--')) {
        const matches = this._options.filter((o) => o.names.some((n) => n.startsWith('--') && n.startsWith(name)));
        if (matches.length === 1) return matches[0];
      }
      return null;
    };

    let i = 0;
    let positionalOnly = false;
    while (i < argv.length) {
      const token = argv[i];
      if (positionalOnly || !token.startsWith('-') || token === '-') {
        extras.push(token);
        i++;
        continue;
      }
      if (token === '--') {
        positionalOnly = true;
        i++;
        continue;
      }
      let name = token;
      let inlineValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
      const opt = findOption(name);
      if (!opt) {
        extras.push(token);
        i++;
        continue;
      }
      if (opt.isHelp) {
        process.stdout.write(this._helpText() + '\n');
        process.exit(0);
      }
      let value;
      if (inlineValue !== null) {
        value = inlineValue;
        i++;
      } else {
        const next = argv[i + 1];
        if (next === undefined || (next.startsWith('-') && next !== '-' && Number.isNaN(Number(next)))) {
          this._error(`argument ${opt.names[0]}: expected one argument`);
        }
        value = next;
        i += 2;
      }
      result[opt.dest] = value;
      seen.add(opt.dest);
    }

    if (extras.length > 0) {
      this._error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    const missing = valueOpts.filter((o) => o.required && !seen.has(o.dest)).map((o) => o.names[0]);
    if (missing.length > 0) {
      this._error(`the following arguments are required: ${missing.join(', ')}`);
    }
    return result;
  }
}

