// Re-implementation of the Draft 7 default type checker's is_type
// behavior, matching jsonschema._types (Draft7Validator.TYPE_CHECKER).

export class UndefinedTypeCheck extends Error {
  constructor(typeName) {
    super(`Type '${typeName}' is unknown to this type checker`);
    this.name = 'UndefinedTypeCheck';
    this.typeName = typeName;
  }
}

const isInteger = (instance) =>
  typeof instance === 'number' && Number.isInteger(instance);

// Draft 7 default type definitions.
const TYPE_CHECKS = {
  array: (instance) => Array.isArray(instance),
  boolean: (instance) => typeof instance === 'boolean',
  integer: isInteger,
  null: (instance) => instance === null,
  number: (instance) => typeof instance === 'number',
  object: (instance) =>
    typeof instance === 'object' && instance !== null && !Array.isArray(instance),
  string: (instance) => typeof instance === 'string',
};

export class TypeChecker {
  constructor(typeChecks = TYPE_CHECKS) {
    this._typeChecks = typeChecks;
  }

  is_type(typeName, instance) {
    const check = this._typeChecks[typeName];
    if (check === undefined) {
      throw new UndefinedTypeCheck(typeName);
    }
    return check(instance);
  }
}

// Draft7Validator(schema).TYPE_CHECKER -- the schema is accepted but, as
// observed from the reference executable, its content does not affect the
// default type checker's behavior.
export class Draft7Validator {
  constructor(schema) {
    this.schema = schema;
    this.TYPE_CHECKER = new TypeChecker();
  }
}

