// Small helpers to keep JSON parsing and printed output aligned with
// Python's json.loads / print behaviors.

// Python's json.loads additionally accepts NaN / Infinity / -Infinity.
export function pyJsonLoads(text) {
  const trimmed = text.trim();
  if (trimmed === 'NaN') return NaN;
  if (trimmed === 'Infinity') return Infinity;
  if (trimmed === '-Infinity') return -Infinity;
  try {
    return JSON.parse(text);
  } catch {
    // Mirror the shape of Python's JSONDecodeError line on stderr.
    const err = new Error('Expecting value: line 1 column 1 (char 0)');
    err.name = 'json.decoder.JSONDecodeError';
    throw err;
  }
}

// Render a value the way Python's print() renders it.
export function pyStr(value) {
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value === null || value === undefined) return 'None';
  return String(value);
}

