// Node.js (ESM) port of test8.py.
// Parses --a (JSON schema string) and --b (type name), then prints
// Draft7Validator(schema).TYPE_CHECKER.is_type(b, b) like Python's print.
import { ArgumentParser } from './lib/argparse.mjs';
import { Draft7Validator, UndefinedTypeCheck } from './lib/draft7Types.mjs';
import { pyJsonLoads, pyStr } from './lib/pyjson.mjs';

const parser = new ArgumentParser();
parser.add_argument('--a', { type: 'str', required: true, help: 'schema (JSON string)' });
parser.add_argument('--b', { type: 'str', required: true, help: 'type name' });
const args = parser.parse_args();

let schema;
try {
  schema = pyJsonLoads(args.a);
} catch (err) {
  process.stderr.write('Traceback (most recent call last):\n');
  process.stderr.write(`${err.name}: ${err.message}\n`);
  process.exit(1);
}

const validator = new Draft7Validator(schema); // Create validator
const typeChecker = validator.TYPE_CHECKER; // Get type checker
let result;
try {
  result = typeChecker.is_type(args.b, args.b); // Check if type exists
} catch (err) {
  if (err instanceof UndefinedTypeCheck) {
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write(`jsonschema.exceptions.UndefinedTypeCheck: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}
console.log(pyStr(result));

